#!/usr/bin/env node
import { readFile } from "node:fs/promises";

import { diff, summarize } from "../src/index.mjs";

const HELP = `objdelta — show what changed between two JSON files

Usage
  objdelta <before.json> <after.json>          Readable change list
  objdelta <before.json> <after.json> --json   Operations as JSON (feed them to patch())

Exit code: 0 when identical, 1 when they differ, 2 on errors.`;

const args = process.argv.slice(2);
const files = args.filter((arg) => !arg.startsWith("--"));

if (args.includes("--help") || files.length !== 2) {
  console.log(HELP);
  process.exitCode = args.includes("--help") ? 0 : 2;
} else {
  try {
    const [before, after] = await Promise.all(files.map(async (file) => JSON.parse(await readFile(file, "utf8"))));
    const ops = diff(before, after);
    if (args.includes("--json")) console.log(JSON.stringify(ops, null, 2));
    else console.log(ops.length ? summarize(ops).join("\n") : "No differences.");
    process.exitCode = ops.length ? 1 : 0;
  } catch (error) {
    console.error(`objdelta: ${error.message}`);
    process.exitCode = 2;
  }
}

// Value inspection, equality and cloning: the two inherited organs.

export const kindOf = (value) => Object.prototype.toString.call(value).slice(8, -1);

export const isObjectLike = (value) => typeof value === "object" && value !== null;

export const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

function bytesOf(view) {
  return view instanceof ArrayBuffer ? new Uint8Array(view) : new Uint8Array(view.buffer, view.byteOffset, view.byteLength);
}

function sameBytes(left, right) {
  const a = bytesOf(left);
  const b = bytesOf(right);
  return a.length === b.length && a.every((byte, index) => byte === b[index]);
}

function findMatchingKey(map, wanted) {
  if (map.has(wanted)) return { found: true, key: wanted };
  for (const key of map.keys()) {
    if (equal(key, wanted)) return { found: true, key };
  }
  return { found: false };
}

/** Deep structural equality. NaN equals NaN; prototypes must match. */
export function equal(a, b) {
  if (a === b) return true;
  if (!isObjectLike(a) || !isObjectLike(b)) return a !== a && b !== b;
  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;

  switch (kindOf(a)) {
    case "Date":
      return a.getTime() === b.getTime();
    case "RegExp":
      return a.source === b.source && a.flags === b.flags;
    case "Array":
      return a.length === b.length && a.every((item, index) => equal(item, b[index]));
    case "Map":
      if (a.size !== b.size) return false;
      for (const [key, value] of a) {
        const match = findMatchingKey(b, key);
        if (!match.found || !equal(value, b.get(match.key))) return false;
      }
      return true;
    case "Set":
      if (a.size !== b.size) return false;
      for (const item of a) {
        if (!b.has(item) && ![...b].some((other) => equal(item, other))) return false;
      }
      return true;
    case "ArrayBuffer":
    case "DataView":
      return sameBytes(a, b);
    default:
      break;
  }
  if (ArrayBuffer.isView(a)) return sameBytes(a, b);

  const keys = Object.keys(a);
  if (keys.length !== Object.keys(b).length) return false;
  return keys.every((key) => hasOwn(b, key) && equal(a[key], b[key]));
}

/** Deep, independent copy. Own "__proto__" keys are copied as plain data. */
export function clone(value) {
  if (!isObjectLike(value)) return value;

  switch (kindOf(value)) {
    case "Date":
      return new Date(value.getTime());
    case "RegExp": {
      const copy = new RegExp(value.source, value.flags);
      copy.lastIndex = value.lastIndex;
      return copy;
    }
    case "Array":
      return Array.from(value, clone);
    case "Map":
      return new Map(Array.from(value, ([key, item]) => [clone(key), clone(item)]));
    case "Set":
      return new Set(Array.from(value, clone));
    case "ArrayBuffer":
      return value.slice(0);
    case "DataView":
      return new DataView(value.buffer.slice(0), value.byteOffset, value.byteLength);
    default:
      break;
  }
  if (ArrayBuffer.isView(value)) return value.slice();

  const copy = Object.create(Object.getPrototypeOf(value));
  for (const key of Object.keys(value)) defineData(copy, key, clone(value[key]));
  return copy;
}

/** Sets a property without ever triggering setters such as __proto__. */
export function defineData(target, key, value) {
  Object.defineProperty(target, key, { value, enumerable: true, writable: true, configurable: true });
}

import { clone, defineData, equal, hasOwn, isObjectLike, kindOf } from "./core.mjs";

export { clone, equal };

/**
 * Lists the operations that turn `before` into `after`.
 * Values inside operations are clones, so they never alias either input.
 */
export function diff(before, after) {
  const ops = [];
  compare(before, after, [], ops);
  return ops;
}

function compare(left, right, path, ops) {
  if (equal(left, right)) return;

  if (Array.isArray(left) && Array.isArray(right)) {
    const shared = Math.min(left.length, right.length);
    for (let index = 0; index < shared; index += 1) compare(left[index], right[index], [...path, index], ops);
    for (let index = shared; index < right.length; index += 1) {
      ops.push({ op: "add", path: [...path, index], value: clone(right[index]) });
    }
    // Remove from the end so earlier indices stay valid while patching.
    for (let index = left.length - 1; index >= right.length; index -= 1) ops.push({ op: "remove", path: [...path, index] });
    return;
  }

  if (isRecord(left) && isRecord(right) && Object.getPrototypeOf(left) === Object.getPrototypeOf(right)) {
    for (const key of Object.keys(left)) {
      if (hasOwn(right, key)) compare(left[key], right[key], [...path, key], ops);
      else ops.push({ op: "remove", path: [...path, key] });
    }
    for (const key of Object.keys(right)) {
      if (!hasOwn(left, key)) ops.push({ op: "add", path: [...path, key], value: clone(right[key]) });
    }
    return;
  }

  ops.push({ op: "replace", path, value: clone(right) });
}

function isRecord(value) {
  return isObjectLike(value) && kindOf(value) === "Object";
}

/** Applies operations to a deep clone of `value`; inputs are never mutated. */
export function patch(value, ops) {
  if (!Array.isArray(ops)) throw new TypeError("patch expects an array of operations.");
  return ops.reduce(applyOperation, clone(value));
}

function applyOperation(root, operation) {
  const { op, path } = operation ?? {};
  if (!["add", "remove", "replace"].includes(op)) throw new TypeError(`Unknown operation "${op}".`);
  if (!Array.isArray(path)) throw new TypeError("Every operation needs a path array.");
  if (path.length === 0) return op === "remove" ? undefined : clone(operation.value);

  const parent = locateParent(root, path);
  const key = path[path.length - 1];

  if (Array.isArray(parent)) {
    const index = Number(key);
    const limit = op === "add" ? parent.length : parent.length - 1;
    if (!Number.isInteger(index) || index < 0 || index > limit) {
      throw new RangeError(`Invalid path ${formatPath(path)}: index ${key} is out of range.`);
    }
    if (op === "add") parent.splice(index, 0, clone(operation.value));
    else if (op === "replace") parent[index] = clone(operation.value);
    else parent.splice(index, 1);
    return root;
  }

  if (op !== "add" && !hasOwn(parent, key)) throw new Error(`Invalid path ${formatPath(path)}: nothing to ${op}.`);
  if (op === "remove") delete parent[key];
  else defineData(parent, key, clone(operation.value));
  return root;
}

function locateParent(root, path) {
  let node = root;
  for (const segment of path.slice(0, -1)) {
    if (!isObjectLike(node) || !hasOwn(node, segment)) {
      throw new Error(`Invalid path ${formatPath(path)}: "${segment}" does not exist.`);
    }
    node = node[segment];
  }
  if (!isObjectLike(node)) throw new Error(`Invalid path ${formatPath(path)}: parent is not an object.`);
  return node;
}

/** Human-readable change lines: "~ user.name", "+ tags[2]", "- legacy". */
export function summarize(ops) {
  const symbols = { add: "+", remove: "-", replace: "~" };
  return ops.map((operation) => `${symbols[operation.op] ?? "?"} ${formatPath(operation.path)}`);
}

export function formatPath(path) {
  if (path.length === 0) return "(root)";
  return path
    .map((segment, index) => {
      if (typeof segment === "number") return `[${segment}]`;
      if (/^[A-Za-z_$][\w$]*$/.test(segment)) return index === 0 ? segment : `.${segment}`;
      return `[${JSON.stringify(segment)}]`;
    })
    .join("");
}

import test from "node:test";
import assert from "node:assert/strict";

import { clone, diff, equal, formatPath, patch } from "../src/index.mjs";

test("equal compares typed arrays and buffers by bytes", () => {
  assert.equal(equal(new Uint8Array([1, 2]), new Uint8Array([1, 2])), true);
  assert.equal(equal(new Uint8Array([1, 2]), new Uint8Array([1, 3])), false);
  assert.equal(equal(new Uint8Array([1]).buffer, new Uint8Array([1]).buffer), true);
});

test("clone keeps class prototypes", () => {
  class Point {
    constructor(x) {
      this.x = x;
    }
  }
  const copy = clone(new Point(3));
  assert.ok(copy instanceof Point);
  assert.equal(copy.x, 3);
});

test("clone and patch never let __proto__ keys pollute prototypes", () => {
  const hostile = JSON.parse('{"__proto__": {"polluted": true}}');
  const copy = clone(hostile);
  assert.equal({}.polluted, undefined);
  assert.equal(Object.getPrototypeOf(copy), Object.prototype);
  const patched = patch({}, [{ op: "add", path: ["__proto__"], value: { polluted: true } }]);
  assert.equal({}.polluted, undefined);
  assert.deepEqual(Object.keys(patched), ["__proto__"]);
});

test("patch removes array items and rejects out-of-range indices", () => {
  assert.deepEqual(patch([1, 2, 3], [{ op: "remove", path: [1] }]), [1, 3]);
  assert.throws(() => patch([1], [{ op: "replace", path: [5], value: 0 }]), RangeError);
});

test("diff of Maps replaces the whole Map", () => {
  const ops = diff({ m: new Map([["a", 1]]) }, { m: new Map([["a", 2]]) });
  assert.equal(ops.length, 1);
  assert.equal(ops[0].op, "replace");
});

test("formatPath quotes keys that are not identifiers", () => {
  assert.equal(formatPath(["a b", 0, "ok"]), '["a b"][0].ok');
  assert.equal(formatPath([]), "(root)");
});
